  const modalCancelBtn = document.getElementById('cte-modal-cancel');
  const modalSendBtn = document.getElementById('cte-modal-send');
  const modalHeading = document.getElementById('cte-modal-heading');
  const submitBtnText = document.getElementById('cte-submit-btn-text');
  const instructionInput = document.getElementById('cte-instruction-input');
